// Field map for the CFPB sample Closing Disclosure (H-25(B)). Generated by scripts/build-cdmap.py — edit the script, not this file.
window.CD_MAP={"src":"https://files.consumerfinance.gov/f/201403_cfpb_closing-disclosure_cover-H25B.pdf","form":"H-25(B) Closing Disclosure — Fixed Rate Loan Sample (CFPB, public domain)","pages":["cd/cd-p1.png","cd/cd-p2.png","cd/cd-p3.png","cd/cd-p4.png","cd/cd-p5.png"],"aspect":1.2941,"fields":[{"id":"p1-head","p":1,"cat":"overview","b":[5.88,5.42,88.24,4.66],"t":"Closing Disclosure (form H-25)","v":"Issued 4/15/2013","what":"The final, five-page statement of the loan's terms and every closing cost. It replaces the HUD-1 and the final Truth-in-Lending statement for most mortgages (TRID, Reg Z §1026.38).","rule":"The borrower must RECEIVE it at least 3 business days before consummation (signing). Received by mail is presumed 3 business days after mailing. A new 3-day wait is required only if the APR becomes inaccurate, the loan product changes, or a prepayment penalty is added (§1026.19(f)).","say":"\"This is your final loan paperwork. It shows the same things your Loan Estimate did, but with the real numbers. We'll compare the two side by side, page by page, before you sign anything.\"","check":"Put the last Loan Estimate next to it. Same loan type, product, rate and amount? If the APR rose more than 1/8% (fixed) the 3-day clock restarts."},{"id":"p1-issued","p":1,"cat":"header","b":[5.88,12.13,30.88,1.63],"t":"Date Issued","v":"4/15/2013","what":"The date the creditor (or settlement agent) issued this version of the CD.","rule":"Start the 3-business-day count from receipt, not issue, unless delivered in person or e-signed. Business day here = every day except Sundays and federal holidays.","say":"\"This is the date your final numbers were sent. The law gives you three business days to review them before signing.\"","check":"Is the closing date at least 3 business days after you RECEIVED it? (Sample shows the same day — that's only because it's an illustration.)"},{"id":"p1-closing","p":1,"cat":"header","b":[5.88,13.52,30.88,1.63],"t":"Closing Date","v":"4/15/2013","what":"The date the borrower signs (consummation). In California escrow states this is usually signing day, which can differ from funding/recording.","rule":"Consummation date drives the 3-day CD receipt rule.","say":"\"This is the day you sign the loan documents. Your three-day review period counts back from here.\"","check":"Matches the escrow instructions and the lock expiration?"},{"id":"p1-disb","p":1,"cat":"header","b":[5.88,14.91,30.88,1.63],"t":"Disbursement Date","v":"4/15/2013","what":"The date the lender's money is paid out — when prepaid interest starts.","rule":"Prepaid interest (Section F) is calculated from this date to the end of the month (or the day before the first payment period).","say":"\"This is when the loan funds. Interest starts on this day, which is why you'll see a few days of interest in Section F.\"","check":"In CA, if funding/recording slips a day, prepaid interest changes — expect a small difference at the final CD."},{"id":"p1-agent","p":1,"cat":"header","b":[5.88,16.3,30.88,2.94],"t":"Settlement Agent & File #","v":"Epsilon Title Co. · 12-3456","what":"The company running the closing (escrow/title) and its file number.","rule":"In California this is the escrow company; title may be the same or a different company.","say":"\"This is the escrow company handling your closing. If anyone calls about wiring money, verify the instructions by calling this company at a number you already know.\"","check":"Wire-fraud check: never wire using instructions sent by email alone."},{"id":"p1-prop","p":1,"cat":"header","b":[5.88,19.08,30.88,2.94],"t":"Property","v":"456 Somewhere Ave, Anytown","what":"The address securing the loan.","rule":"Must match the appraisal, title and the deed of trust.","say":"\"This is the home the loan is secured by.\"","check":"Unit number / legal description matches the purchase contract."},{"id":"p1-price","p":1,"cat":"header","b":[5.88,21.85,30.88,1.63],"t":"Sale Price (or Appraised Value on a refinance)","v":"$180,000","what":"Purchase price from the contract. On a refinance this line reads 'Appraised Prop. Value' (or 'Estimated' if no appraisal).","rule":"LTV = loan amount ÷ the lesser of price or appraised value (purchase).","say":"\"This is the contract price you agreed to.\"","check":"Matches the final purchase contract and any counter-offers/addenda."},{"id":"p1-parties","p":1,"cat":"header","b":[37.25,12.13,32.19,9.51],"t":"Transaction Information — Borrower, Seller, Lender","v":"Michael Jones & Mary Stone · Steve Cole & Amy Doe · Ficus Bank","what":"Who's in the deal. The lender is the creditor whose name is on the note — for a brokered loan this is the wholesale lender, not the broker.","rule":"Names must match the note and deed of trust exactly.","say":"\"These are the buyers, the sellers, and the lender funding your loan. As your broker, I arranged the loan; the lender on this line is who you'll make payments to (or their servicer).\"","check":"Spelling, middle initials, vesting — mistakes here delay recording."},{"id":"p1-term","p":1,"cat":"loaninfo","b":[70.59,12.13,23.53,1.63],"t":"Loan Term","v":"30 years","what":"Number of years until the loan is paid off.","rule":"Must match the note.","say":"\"Your loan is set up to be paid off over 30 years.\"","check":"Same as the Loan Estimate."},{"id":"p1-purpose","p":1,"cat":"loaninfo","b":[70.59,13.52,23.53,1.63],"t":"Purpose","v":"Purchase","what":"Purchase, Refinance, Construction or Home Equity Loan.","rule":"","say":"\"This loan is for buying the home.\"","check":"Same as the Loan Estimate."},{"id":"p1-product","p":1,"cat":"loaninfo","b":[70.59,14.91,23.53,1.63],"t":"Product","v":"Fixed Rate","what":"The rate type and features (Fixed Rate, 5/6 Adjustable Rate, Interest Only, Step Rate…).","rule":"A change in product after the last CD requires a NEW 3-business-day waiting period.","say":"\"Your rate is fixed — your principal and interest never change.\"","check":"Product changed from the LE/initial CD? That restarts the 3-day clock."},{"id":"p1-type","p":1,"cat":"loaninfo","b":[70.59,17.69,23.53,2.94],"t":"Loan Type","v":"Conventional","what":"Conventional, FHA, VA, or Other (e.g., USDA).","rule":"Determines MI vs MIP vs VA funding fee rules and concession limits.","say":"\"This is a conventional loan — not government-insured.\"","check":"Matches the program you locked."},{"id":"p1-loanid","p":1,"cat":"loaninfo","b":[70.59,20.47,23.53,1.63],"t":"Loan ID #","v":"123456789","what":"The creditor's loan number. Appears in the footer of every page.","rule":"","say":"\"This is your loan number — have it handy when you call the lender or servicer.\"","check":"Same number on every page (the official sample has a typo on page 4)."},{"id":"p1-mic","p":1,"cat":"loaninfo","b":[70.59,21.85,23.53,1.63],"t":"MIC # (Mortgage Insurance Case number)","v":"000654321","what":"The mortgage insurance certificate (conventional PMI) or FHA case number.","rule":"Blank when there's no mortgage insurance (e.g., VA, or 20%+ down conventional).","say":"\"This is your mortgage insurance certificate number, because you put less than 20% down.\"","check":"Present if MI appears on page 1 and page 2."},{"id":"p1-amt","p":1,"cat":"terms","b":[5.88,28.49,88.24,1.94],"t":"Loan Amount","v":"$162,000 · can't increase: NO","what":"The amount borrowed (includes any financed FHA UFMIP / VA funding fee / USDA guarantee fee).","rule":"The 'Can this amount increase after closing?' column says YES only for negative amortization.","say":"\"You're borrowing $162,000. That number can't go up after closing.\"","check":"$180,000 price − $18,000 down = $162,000 (90% LTV). Matches the LE."},{"id":"p1-rate","p":1,"cat":"terms","b":[5.88,31.9,88.24,1.94],"t":"Interest Rate","v":"3.875% · can't increase: NO","what":"The note rate. Not the APR.","rule":"For an ARM the right column shows how and when it can change, the first change and the cap.","say":"\"Your interest rate is 3.875% and it's locked for the life of the loan.\"","check":"Matches the rate lock confirmation. A lower rate with higher points (or vice-versa) should match what you chose."},{"id":"p1-pi","p":1,"cat":"terms","b":[5.88,34.74,88.24,4.57],"t":"Monthly Principal & Interest","v":"$761.78","what":"The principal and interest payment only — no taxes, insurance or MI.","rule":"P&I = standard amortization of $162,000 at 3.875% over 360 months = $761.78.","say":"\"Of your payment, $761.78 goes to principal and interest. Taxes, insurance and mortgage insurance are added in Projected Payments below.\"","check":"Recalculate: amortization of loan amount at the note rate."},{"id":"p1-ppp","p":1,"cat":"terms","b":[5.88,42.88,88.24,3.26],"t":"Prepayment Penalty","v":"YES — as high as $3,240 in the first 2 years","what":"Whether paying the loan off early (sale or refinance) triggers a penalty.","rule":"Only allowed on certain fixed-rate qualified mortgages that are not higher-priced: max 2% of the balance in years 1–2, 1% in year 3, none after; the lender must also offer an alternative without one (§1026.43(g)). Adding one after the last CD restarts the 3-day wait. Most loans today have NONE.","say":"\"This sample loan has a penalty of up to $3,240 if you pay it off within 2 years. Yours says NO — you can pay it off or refinance any time without a penalty.\"","check":"Ours should read NO. If YES, stop and review — it should never be a surprise."},{"id":"p1-balloon","p":1,"cat":"terms","b":[5.88,46.83,88.24,1.94],"t":"Balloon Payment","v":"NO","what":"Whether a large lump-sum payment is due at the end.","rule":"Balloons are generally not allowed on QM loans (with narrow small-creditor exceptions).","say":"\"There's no balloon — the loan pays off completely with your regular payments.\"","check":"Should read NO on agency loans."},{"id":"p1-pp","p":1,"cat":"payments","b":[5.88,51.47,88.24,21.05],"t":"Projected Payments","v":"Years 1–7: $1,050.26 · Years 8–30: $967.91","what":"How the total payment changes over time — up to 4 columns (changes in MI, rate, interest-only periods).","rule":"Mortgage insurance falls off in year 8 here because borrower-paid PMI terminates automatically when the loan reaches 78% of the original value on the original schedule (Homeowners Protection Act). FHA MIP can be for life.","say":"\"Your payment starts at $1,050.26 — principal and interest $761.78, mortgage insurance $82.35 and escrow $206.13. Around year 8 the mortgage insurance drops off, so it goes to about $967.91. Escrow can change each year with taxes and insurance.\"","check":"$761.78 + $82.35 + $206.13 = $1,050.26. Escrow matches page 4."},{"id":"p1-mi","p":1,"cat":"payments","b":[5.88,60.92,88.24,1.9],"t":"Mortgage Insurance (monthly)","v":"$82.35 years 1–7, then —","what":"The monthly MI premium (conventional PMI, FHA annual MIP or USDA annual fee).","rule":"Conventional PMI: can request removal at 80% LTV, automatic at 78% of the original value. FHA: 11 years if 10%+ down, otherwise life of loan.","say":"\"Because you put less than 20% down, there's $82.35 a month of mortgage insurance. It protects the lender, not you, and it comes off automatically once you've paid down to 78% of the original value — or you can ask to remove it at 80%.\"","check":"Matches the MI quote / LE. Removal plan explained."},{"id":"p1-esc","p":1,"cat":"payments","b":[5.88,63.32,88.24,3.21],"t":"Estimated Escrow (monthly)","v":"$206.13","what":"The monthly amount collected for property taxes and homeowner's insurance.","rule":"= escrowed property costs over year 1 ÷ 12 (page 4: $2,473.56 ÷ 12).","say":"\"Each month $206.13 goes into your escrow account, and the servicer pays your property taxes and insurance for you. It can change once a year when they do the escrow analysis.\"","check":"Tax estimate uses the CA purchase-price basis (≈1.1–1.25% + local assessments), not the seller's old bill."},{"id":"p1-total","p":1,"cat":"payments","b":[5.88,67.03,88.24,3.26],"t":"Estimated Total Monthly Payment","v":"$1,050.26 → $967.91","what":"Principal & interest + MI + escrow — what will actually come out of the borrower's account (HOA dues are paid separately).","rule":"","say":"\"This is your actual monthly payment: $1,050.26. HOA dues are separate and paid to the association.\"","check":"Compare to the payment the borrower qualified with and expects."},{"id":"p1-tia","p":1,"cat":"payments","b":[5.88,72.58,88.24,10.51],"t":"Estimated Taxes, Insurance & Assessments","v":"$356.13 a month","what":"ALL property costs per month, escrowed or not: taxes + insurance (in escrow) + HOA dues (not in escrow).","rule":"$206.13 escrowed + $150 HOA = $356.13. 'In escrow?' shows what the servicer pays vs what the borrower pays directly.","say":"\"Your total property costs are about $356 a month. $206 is in your payment; the $150 HOA you pay directly to the HOA.\"","check":"Every non-escrowed cost (HOA, Mello-Roos if billed separately) listed."},{"id":"p1-cc","p":1,"cat":"costs","b":[5.88,86.07,88.24,3.26],"t":"Closing Costs","v":"$9,712.10","what":"Total borrower-paid closing costs = Loan Costs (D) + Other Costs (I) − Lender Credits.","rule":"= page 2 line J.","say":"\"Your total closing costs are $9,712.10 — about $4,694 for the loan itself and $5,018 for taxes, prepaid items, escrow and other costs. We'll go through each one on page 2.\"","check":"Compare to the LE's closing costs; differences explained on page 3."},{"id":"p1-ctc","p":1,"cat":"costs","b":[5.88,90.49,88.24,1.94],"t":"Cash to Close","v":"$14,147.26","what":"The money the borrower must bring to closing, after the deposit, credits and adjustments.","rule":"= page 3 'Calculating Cash to Close' = K − L on the summary.","say":"\"You'll need to bring $14,147.26 to closing by wire or cashier's check. Your $10,000 deposit is already counted. Call escrow at a number you already have to confirm wiring instructions.\"","check":"Funds verified in the file cover this plus required reserves."},{"id":"p2-cols","p":2,"cat":"p2","b":[50.98,6.86,43.14,1.59],"t":"Who pays & when (columns)","v":"Borrower-Paid · Seller-Paid · Paid by Others, each at/before closing","what":"Every fee is shown in the column of who pays it and whether it was paid at or before closing.","rule":"'Paid by Others' = lender, broker, builder, or another third party (lender-paid broker comp shows here as paid by the lender).","say":"\"These columns show who's paying each fee. Anything in the seller or 'others' columns isn't coming out of your pocket.\"","check":"Seller credits applied as the contract says."},{"id":"p2-a","p":2,"cat":"A","b":[5.88,8.34,88.24,1.63],"t":"A. Origination Charges","v":"$1,802.00","what":"Everything the lender (and broker) charge to make the loan: points, origination/application/underwriting/processing fees, broker compensation.","rule":"ZERO tolerance — cannot increase from the LE without a valid changed circumstance. Points and fees count toward the QM 3% cap (2026: 3% for loans ≥ $137,958).","say":"\"These are the fees for making your loan. This total can't go up from your Loan Estimate unless something about the loan changed.\"","check":"Compare line by line with LE Section A. Any increase needs a revised LE for a valid reason — otherwise it's cured with a refund."},{"id":"p2-a1","p":2,"cat":"A","b":[5.88,9.76,88.24,1.59],"t":"A.01 Points (discount points)","v":"0.25% = $405.00","what":"Optional prepaid interest paid to lower the rate.","rule":"Discount points must actually buy down the rate to be excluded from QM points & fees (bona fide). Zero tolerance.","say":"\"You paid a quarter point, $405, to get a lower rate. At roughly $X less per month, it pays for itself in about Y months.\"","check":"Break-even: points ÷ monthly savings. If they plan to move or refinance sooner, points may not make sense."},{"id":"p2-a2","p":2,"cat":"A","b":[5.88,11.03,88.24,1.59],"t":"A.02 Application Fee","v":"$300.00","what":"A lender fee to process the application.","rule":"Zero tolerance. Before the LE, the only fee allowed is a credit-report fee.","say":"\"This is the lender's application fee.\"","check":"On the LE at the same amount."},{"id":"p2-a3","p":2,"cat":"A","b":[5.88,12.29,88.24,1.59],"t":"A.03 Underwriting Fee","v":"$1,097.00","what":"The lender's fee to underwrite and approve the loan.","rule":"Zero tolerance.","say":"\"This is the lender's fee for reviewing and approving your loan.\"","check":"Same as LE. Broker compensation paid by the borrower would also appear in Section A, named to the broker."},{"id":"p2-b","p":2,"cat":"B","b":[5.88,19.95,88.24,1.63],"t":"B. Services You Cannot Shop For","v":"$236.55","what":"Third-party services the lender chose and the borrower couldn't shop for (appraisal, credit, flood, tax service).","rule":"ZERO tolerance if the provider is the lender or its affiliate or the borrower wasn't allowed to shop; 10% bucket otherwise for affiliates… in practice, B items are zero tolerance when the borrower couldn't shop. Fees show who they're paid to.","say":"\"The lender ordered these services — the appraisal, credit report and flood check. You couldn't shop for them, so they generally can't increase from your Loan Estimate.\"","check":"Each item vs LE Section B; increases need a changed circumstance (e.g., second appraisal required)."},{"id":"p2-b1","p":2,"cat":"B","b":[5.88,21.38,88.24,1.59],"t":"B.01 Appraisal Fee","v":"$405.00 — paid by others","what":"Paid to the appraiser (or AMC).","rule":"Borrower must receive a copy of the appraisal at least 3 business days before closing (ECOA, Reg B).","say":"\"This is the appraisal. In this sample someone else paid it. You'll get a copy of the appraisal at least three days before closing.\"","check":"Appraisal delivered and acknowledged."},{"id":"p2-b2","p":2,"cat":"B","b":[5.88,22.64,88.24,1.59],"t":"B.02 Credit Report Fee","v":"$29.80 paid before closing","what":"Tri-merge credit report.","rule":"The only fee that may be collected before the borrower receives the LE and indicates intent to proceed.","say":"\"This is the credit report you paid for at application — it's already paid, so it shows in the 'before closing' column.\"","check":"Shows in 'Before Closing' if already paid."},{"id":"p2-b3","p":2,"cat":"B","b":[5.88,23.91,88.24,1.59],"t":"B.03 Flood Determination Fee","v":"$20.00","what":"Certifies whether the property is in a FEMA special flood hazard area.","rule":"Required on every federally related loan.","say":"\"This checks whether the home is in a flood zone, which decides whether flood insurance is required.\"","check":"If in a flood zone, flood insurance premium appears in F/G."},{"id":"p2-b4","p":2,"cat":"B","b":[5.88,25.17,88.24,1.59],"t":"B.04 Flood Monitoring Fee","v":"$31.75","what":"Life-of-loan monitoring for FEMA map changes.","rule":"","say":"\"This keeps watching the flood maps for the life of the loan.\"","check":""},{"id":"p2-b5","p":2,"cat":"B","b":[5.88,26.43,88.24,1.59],"t":"B.05 Tax Monitoring Fee","v":"$75.00","what":"Tax service that tracks property tax bills and payments for the servicer.","rule":"","say":"\"This makes sure your property taxes get paid on time from escrow.\"","check":""},{"id":"p2-b6","p":2,"cat":"B","b":[5.88,27.69,88.24,1.59],"t":"B.06 Tax Status Research Fee","v":"$80.00","what":"Confirms current tax status (no delinquencies).","rule":"","say":"\"This confirms there are no unpaid property taxes on the home.\"","check":""},{"id":"p2-c","p":2,"cat":"C","b":[5.88,34.1,88.24,1.63],"t":"C. Services You Can Shop For","v":"$2,655.50","what":"Third-party services the borrower was allowed to shop for (title, survey, pest).","rule":"10% tolerance (in total, together with recording fees) if the borrower chose a provider from the lender's Written List of Providers; NO tolerance if they chose their own. All title charges start with 'Title –'.","say":"\"These are services you were allowed to shop for. If you used a company from our list, the total can't go up more than 10%. Title fees are here.\"","check":"Sum C + recording fees vs LE; over 10% → cure."},{"id":"p2-c1","p":2,"cat":"C","b":[5.88,35.52,88.24,1.59],"t":"C.01 Pest Inspection Fee","v":"$120.50","what":"Termite/wood-destroying-pest inspection.","rule":"Required by some loan programs (VA/FHA in some areas) or by the contract.","say":"\"This is the termite inspection.\"","check":"Who pays per the purchase contract (often the seller in CA)."},{"id":"p2-c2","p":2,"cat":"C","b":[5.88,36.78,88.24,1.59],"t":"C.02 Survey Fee","v":"$85.00 (seller-paid)","what":"Property survey.","rule":"","say":"\"The survey confirms the lot lines; the seller is paying it here.\"","check":""},{"id":"p2-c3","p":2,"cat":"C","b":[5.88,38.05,88.24,1.59],"t":"C.03 Title – Insurance Binder","v":"$650.00","what":"Commitment to issue title insurance.","rule":"","say":"\"This is the title company's commitment to insure the title.\"","check":""},{"id":"p2-c4","p":2,"cat":"C","b":[5.88,39.31,88.24,1.59],"t":"C.04 Title – Lender's Title Insurance","v":"$500.00","what":"Protects the LENDER against title defects; required by the lender.","rule":"Disclosed at the full lender's-policy premium even when the owner's policy is bought (any simultaneous-issue discount goes to the owner's policy line in H) — §1026.37(g)(4).","say":"\"This title policy protects the lender. The policy that protects you is the owner's policy in Section H.\"","check":"Matches the title quote."},{"id":"p2-c5","p":2,"cat":"C","b":[5.88,40.57,88.24,1.59],"t":"C.05 Title – Settlement Agent (Escrow) Fee","v":"$500.00","what":"Escrow/settlement fee to run the closing.","rule":"In CA, buyer/seller split of escrow fees is local custom and the contract.","say":"\"This is the escrow fee for handling the closing.\"","check":"Split per contract."},{"id":"p2-c6","p":2,"cat":"C","b":[5.88,41.83,88.24,1.59],"t":"C.06 Title – Title Search","v":"$800.00","what":"Searches public records for liens and ownership.","rule":"","say":"\"This searches the records to make sure the seller can deliver clean title.\"","check":""},{"id":"p2-d","p":2,"cat":"D","b":[5.88,45.71,88.24,2.94],"t":"D. Total Loan Costs","v":"$4,694.05 ($4,664.25 at closing + $29.80 before)","what":"A + B + C, borrower-paid.","rule":"Section D is included in Total of Payments (page 5).","say":"\"Altogether the loan-related costs are $4,694.05.\"","check":"= A + B + C."},{"id":"p2-e","p":2,"cat":"E","b":[5.88,51.87,88.24,1.63],"t":"E. Taxes & Government Fees","v":"$85.00","what":"Recording fees and transfer taxes.","rule":"Recording fees: 10% bucket. Transfer taxes: ZERO tolerance. In CA, documentary transfer tax is customarily seller-paid ($1.10 per $1,000 county + any city).","say":"\"These are government fees to record your deed and loan. The seller is paying the transfer tax here.\"","check":"Transfer tax column (seller vs buyer) per contract and county custom."},{"id":"p2-e1","p":2,"cat":"E","b":[5.88,53.3,88.24,1.59],"t":"E.01 Recording Fees","v":"Deed $40 · Mortgage $45","what":"County fees to record the deed and deed of trust.","rule":"10% tolerance bucket. CA adds the $75 SB2 housing fee per document in many cases.","say":"\"These record your ownership and the loan with the county.\"","check":""},{"id":"p2-e2","p":2,"cat":"E","b":[5.88,54.56,88.24,1.59],"t":"E.02 Transfer Tax","v":"$950.00 (seller-paid)","what":"State/county/city tax on the transfer of the property.","rule":"Zero tolerance for the borrower's share.","say":"\"This tax is charged when the property changes hands — the seller is paying it.\"","check":""},{"id":"p2-f","p":2,"cat":"F","b":[5.88,55.91,88.24,1.63],"t":"F. Prepaids","v":"$2,120.80","what":"Items paid in advance at closing: first year of insurance, prepaid interest, some property taxes.","rule":"No tolerance limit, but must be good-faith estimates.","say":"\"Prepaids aren't fees — they're your own costs paid in advance: a year of insurance, interest for the rest of this month, and some taxes.\"","check":"Insurance premium matches the HOI declaration page."},{"id":"p2-f1","p":2,"cat":"F","b":[5.88,57.34,88.24,1.59],"t":"F.01 Homeowner's Insurance Premium (12 mo.)","v":"$1,209.96","what":"First-year homeowner's insurance premium, paid to the insurer.","rule":"Most lenders require the first year paid at closing.","say":"\"This is your first full year of homeowner's insurance.\"","check":"Matches the policy declarations ($100.83 × 12 = $1,209.96)."},{"id":"p2-f2","p":2,"cat":"F","b":[5.88,58.6,88.24,1.59],"t":"F.02 Mortgage Insurance Premium","v":"(blank in this sample)","what":"Single-premium MI or FHA upfront MIP if paid in cash (financed UFMIP goes into the loan amount instead).","rule":"","say":"\"No upfront mortgage insurance on this loan — it's paid monthly instead.\"","check":"FHA: UFMIP 1.75% shows here if not financed."},{"id":"p2-f3","p":2,"cat":"F","b":[5.88,59.87,88.24,1.59],"t":"F.03 Prepaid Interest","v":"$17.44/day × 16 days (4/15–5/1) = $279.04","what":"Interest from funding to the end of the month. Mortgage interest is paid in arrears, so the first payment (June 1) covers May.","rule":"$162,000 × 3.875% ÷ 360 = $17.44 per day (this sample uses a 360-day year; many lenders use 365).","say":"\"Mortgage interest is paid after the month it's owed. This covers the days from closing to the end of April. Your first payment isn't until June 1 — closing late in the month means less prepaid interest, but it doesn't save money overall.\"","check":"Per-diem math and the first payment date."},{"id":"p2-f4","p":2,"cat":"F","b":[5.88,61.13,88.24,1.59],"t":"F.04 Property Taxes (6 mo.)","v":"$631.80","what":"Property taxes due soon after closing, paid in advance.","rule":"In CA, taxes are due Nov 1 and Feb 1 (delinquent Dec 10 / Apr 10); a supplemental tax bill comes after purchase — warn the buyer.","say":"\"This pays the next property tax installment. In California you'll also get a supplemental tax bill after the purchase, which usually isn't paid from escrow — set money aside for it.\"","check":"Next installment due date vs closing date."},{"id":"p2-g","p":2,"cat":"G","b":[5.88,63.74,88.24,1.63],"t":"G. Initial Escrow Payment at Closing","v":"$412.25","what":"Starting balance for the escrow account so it has enough when bills come due.","rule":"RESPA allows a cushion of up to 2 months of escrow (Reg X §1024.17).","say":"\"This seeds your escrow account so there's enough money when the next tax and insurance bills come due.\"","check":"= page 4 Initial Escrow Payment."},{"id":"p2-g1","p":2,"cat":"G","b":[5.88,65.17,88.24,1.59],"t":"G.01 Homeowner's Insurance (2 mo.)","v":"$100.83 × 2 = $201.66","what":"Months of insurance reserve.","rule":"","say":"\"Two months of insurance as a cushion.\"","check":""},{"id":"p2-g3","p":2,"cat":"G","b":[5.88,67.69,88.24,1.59],"t":"G.03 Property Taxes (2 mo.)","v":"$105.30 × 2 = $210.60","what":"Months of tax reserve.","rule":"","say":"\"Two months of property taxes as a cushion.\"","check":""},{"id":"p2-g8","p":2,"cat":"G","b":[5.88,74.01,88.24,1.59],"t":"G.08 Aggregate Adjustment","v":"−$0.01","what":"Reduces the escrow deposit so the account never holds more than the allowed cushion.","rule":"Always zero or negative.","say":"\"This small adjustment makes sure the lender isn't holding more than the law allows.\"","check":""},{"id":"p2-h","p":2,"cat":"H","b":[5.88,75.36,88.24,1.63],"t":"H. Other","v":"$2,400.00 (borrower)","what":"Everything else: HOA fees, inspections, warranty, commissions, owner's title.","rule":"No tolerance limit (not required by the lender).","say":"\"These aren't loan costs — they're other costs of the purchase, like the HOA and the owner's title policy.\"","check":"Each item per the contract and HOA demand."},{"id":"p2-h1","p":2,"cat":"H","b":[5.88,76.78,88.24,1.59],"t":"H.01 HOA Capital Contribution","v":"$500.00","what":"One-time HOA transfer/capital fee.","rule":"","say":"\"A one-time fee the HOA charges new owners.\"","check":"Per HOA demand."},{"id":"p2-h2","p":2,"cat":"H","b":[5.88,78.05,88.24,1.59],"t":"H.02 HOA Processing Fee","v":"$150.00","what":"HOA transfer/document processing.","rule":"","say":"\"The HOA's fee to transfer the account to you.\"","check":""},{"id":"p2-h3","p":2,"cat":"H","b":[5.88,79.31,88.24,1.59],"t":"H.03 Home Inspection Fee","v":"$750 (borrower) · $750 (seller)","what":"General home inspection.","rule":"","say":"\"Your home inspection.\"","check":""},{"id":"p2-h4","p":2,"cat":"H","b":[5.88,80.57,88.24,1.59],"t":"H.04 Home Warranty Fee","v":"$450 (seller-paid)","what":"One-year home warranty.","rule":"","say":"\"A home warranty for the first year — paid by the seller here.\"","check":""},{"id":"p2-h5","p":2,"cat":"H","b":[5.88,81.84,88.24,1.59],"t":"H.05–06 Real Estate Commissions","v":"$5,700 + $5,700 (seller-paid)","what":"Listing and buyer-agent commissions.","rule":"Commissions are negotiable. After the 2024 NAR settlement, buyer-agent compensation is set in a written buyer agreement.","say":"\"These are the agents' commissions, paid by the seller in this sale.\"","check":"Per listing and buyer-broker agreements."},{"id":"p2-h7","p":2,"cat":"H","b":[5.88,84.36,88.24,1.59],"t":"H.07 Title – Owner's Title Insurance (optional)","v":"$1,000.00","what":"Protects the BUYER's ownership against title defects. Marked optional because the lender doesn't require it.","rule":"Shown as owner's premium + simultaneous lender's premium − full lender's premium (§1026.37(g)(4)) — so this number can look different from the title company's rate card.","say":"\"This policy protects YOU if someone ever claims an ownership problem from before you bought. It's 'optional' only because the lender doesn't require it — I strongly recommend it. In much of Southern California the seller customarily pays it — check your contract.\"","check":"Who pays per contract/county custom."},{"id":"p2-i","p":2,"cat":"I","b":[5.88,86.97,88.24,2.94],"t":"I. Total Other Costs","v":"$5,018.05","what":"E + F + G + H, borrower-paid.","rule":"","say":"\"The non-loan costs add up to $5,018.05.\"","check":"= E + F + G + H."},{"id":"p2-j","p":2,"cat":"J","b":[5.88,91.6,88.24,2.94],"t":"J. Total Closing Costs","v":"$9,712.10 ($9,682.30 at closing + $29.80 before)","what":"D + I − Lender Credits. Carries to page 1 and page 3.","rule":"","say":"\"Total closing costs: $9,712.10, of which $29.80 you already paid for the credit report.\"","check":"= D + I − credits."},{"id":"p2-lc","p":2,"cat":"J","b":[5.88,94.28,88.24,1.59],"t":"Lender Credits","v":"$0","what":"Money from the lender toward closing costs (usually from choosing a slightly higher rate).","rule":"The lender credit can't DECREASE from the LE without a valid changed circumstance (zero tolerance). Tolerance cures appear as a credit here: 'includes $X credit for increase in closing costs above legal limit'.","say":"\"No lender credit on this loan. If there were one, it would reduce your closing costs here.\"","check":"Equal to or larger than the LE's lender credit."},{"id":"p3-ctc","p":3,"cat":"p3","b":[5.88,4.88,88.24,3.26],"t":"Calculating Cash to Close","v":"LE $16,054.00 → Final $14,147.26","what":"Compares each piece of cash to close from the Loan Estimate to the final, with 'Did this change?' and the reason.","rule":"Any YES must say why and where to look.","say":"\"This table explains why your cash to close is different from the Loan Estimate.\"","check":"Every YES has an explanation you can read to the borrower."},{"id":"p3-tcc","p":3,"cat":"p3","b":[5.88,8.82,88.24,1.59],"t":"Total Closing Costs (J)","v":"$8,054.00 → $9,712.10 · YES","what":"Change in total closing costs. The table says whether it exceeded the legal limits and by how much.","rule":"If the increase is over tolerance, the CD shows the cure amount.","say":"\"Your closing costs went up from the estimate, mostly because of items in Sections F and G that are based on actual dates and premiums. None of the fees with limits went over those limits.\"","check":"Look for 'Increase exceeds legal limits by $X' — that's a cure owed."},{"id":"p3-pbc","p":3,"cat":"p3","b":[5.88,10.59,88.24,1.59],"t":"Closing Costs Paid Before Closing","v":"$0 → −$29.80 · YES","what":"Costs already paid (credit report), subtracted from cash to close.","rule":"","say":"\"You already paid $29.80 for the credit report, so it comes off what you bring.\"","check":""},{"id":"p3-fin","p":3,"cat":"p3","b":[5.88,12.36,88.24,2.91],"t":"Closing Costs Financed","v":"$0","what":"Closing costs rolled into the loan amount (common on refinances).","rule":"","say":"\"None of your costs were added to the loan.\"","check":"Refi: should equal loan amount − payoffs when costs are financed."},{"id":"p3-dp","p":3,"cat":"p3","b":[5.88,15.26,88.24,1.59],"t":"Down Payment / Funds from Borrower","v":"$18,000 → $18,000 · NO","what":"Price minus loan amount.","rule":"","say":"\"Your down payment is $18,000 — 10%.\"","check":""},{"id":"p3-dep","p":3,"cat":"p3","b":[5.88,17.03,88.24,1.59],"t":"Deposit","v":"−$10,000","what":"Earnest money already given to escrow — a credit toward cash to close.","rule":"","say":"\"Your $10,000 good-faith deposit is already at escrow and counts toward what you owe.\"","check":"EMD receipt in file."},{"id":"p3-ffb","p":3,"cat":"p3","b":[5.88,18.8,88.24,1.59],"t":"Funds for Borrower","v":"$0","what":"Cash back to the borrower from the loan (e.g., cash-out refi).","rule":"","say":"\"You're not receiving any loan funds back.\"","check":""},{"id":"p3-sc","p":3,"cat":"p3","b":[5.88,20.57,88.24,1.59],"t":"Seller Credits","v":"$0 → −$2,500 · YES","what":"Seller-paid credit toward the buyer's costs.","rule":"Must stay within program concession limits (conventional 3–9% by LTV; FHA 6%; VA 4% + normal costs) and can't exceed actual costs.","say":"\"The seller is giving you a $2,500 credit, which reduces what you bring.\"","check":"Matches the contract addendum; within the program's limit."},{"id":"p3-adj","p":3,"cat":"p3","b":[5.88,22.33,88.24,1.59],"t":"Adjustments and Other Credits","v":"$0 → −$1,035.04 · YES","what":"Prorations and other credits (taxes, HOA, title rebate).","rule":"Details on the summary: −$750 title rebate − $365.04 unpaid city taxes + $80 HOA paid ahead = −$1,035.04.","say":"\"These are fair-share adjustments: the seller owes you for taxes up to closing, you reimburse the seller for HOA dues they prepaid, and the title company gave a $750 rebate.\"","check":"Math adds up to the summary sections."},{"id":"p3-total","p":3,"cat":"p3","b":[5.88,24.06,88.24,1.63],"t":"Cash to Close (final)","v":"$14,147.26","what":"The bottom line — what to bring.","rule":"","say":"\"So the final amount to bring is $14,147.26.\"","check":"Same as page 1 and the K − L calculation."},{"id":"p3-k","p":3,"cat":"p3","b":[5.88,33.45,44.77,25.5],"t":"K. Due from Borrower at Closing","v":"$189,762.30","what":"Everything the borrower owes: price + closing costs (J) + adjustments for items the seller paid in advance (e.g., HOA dues already paid for the rest of the month).","rule":"","say":"\"This is everything you owe: the price, your closing costs and a small HOA reimbursement.\"","check":"$180,000 + $9,682.30 + $80 = $189,762.30."},{"id":"p3-l","p":3,"cat":"p3","b":[5.88,59.02,44.77,29.54],"t":"L. Paid Already by or on Behalf of Borrower","v":"$175,615.04","what":"Everything already paid or credited: deposit, the new loan, seller credit, other credits, unpaid seller taxes.","rule":"","say":"\"This is what's already covered — your deposit, the loan, the seller credit, the title rebate and the seller's share of taxes.\"","check":"$10,000 + $162,000 + $2,500 + $750 + $365.04 = $175,615.04."},{"id":"p3-calc","p":3,"cat":"p3","b":[5.88,90.37,44.77,4.22],"t":"Calculation — Cash to Close","v":"$189,762.30 − $175,615.04 = $14,147.26 From Borrower","what":"K minus L. 'From' means the borrower brings money; 'To' means the borrower receives money.","rule":"","say":"\"K minus L is the $14,147.26 you bring.\"","check":""},{"id":"p3-m","p":3,"cat":"p3","b":[50.98,33.45,43.14,25.5],"t":"M. Due to Seller at Closing (seller's side)","v":"Sale price + prorations owed to seller","what":"The seller's side of the ledger. Lenders may omit the seller columns on the buyer's CD (a separate seller CD is used).","rule":"","say":"\"This side shows the seller's numbers — you don't need to worry about it.\"","check":""},{"id":"p3-n","p":3,"cat":"p3","b":[50.98,59.02,43.14,29.54],"t":"N. Due from Seller at Closing","v":"Payoffs, seller-paid costs, credits","what":"Seller's payoffs and costs.","rule":"","say":"\"These are the seller's payoffs and costs.\"","check":""},{"id":"p4-assume","p":4,"cat":"p4","b":[5.88,11.11,43.14,8.4],"t":"Assumption","v":"Will not allow assumption","what":"Whether a future buyer can take over this loan on its terms.","rule":"Conventional loans are generally not assumable; FHA and VA loans are assumable with lender approval (a real selling point when rates rise).","say":"\"If you sell, the buyer can't take over this loan — it gets paid off.\" (FHA/VA: \"A qualified buyer may be able to take over your low rate — that can help you sell later.\")","check":"FHA/VA should show 'will allow, under certain conditions'."},{"id":"p4-demand","p":4,"cat":"p4","b":[5.88,19.57,43.14,8.65],"t":"Demand Feature","v":"Does not have one","what":"Whether the lender can demand full repayment early for reasons other than default.","rule":"","say":"\"The lender can't call the loan due early as long as you keep your agreement.\"","check":"Should be 'does not have'."},{"id":"p4-late","p":4,"cat":"p4","b":[5.88,28.28,43.14,5.24],"t":"Late Payment","v":"More than 15 days late → 5% of P&I","what":"The late-charge terms from the note.","rule":"FHA and VA notes use 4% after 15 days; conventional is commonly 5%.","say":"\"Payments are due on the 1st. If one is more than 15 days late, there's a late fee of 5% of principal and interest — about $38. Set up autopay.\"","check":"Matches the note."},{"id":"p4-negam","p":4,"cat":"p4","b":[5.88,33.58,43.14,19.25],"t":"Negative Amortization","v":"Does not have","what":"Whether the balance can grow because payments don't cover interest.","rule":"Not allowed on qualified mortgages.","say":"\"Your balance only goes down — never up.\"","check":"Should be 'do not have'."},{"id":"p4-partial","p":4,"cat":"p4","b":[5.88,52.9,43.14,13.13],"t":"Partial Payments","v":"May accept and apply","what":"How the lender handles less than a full payment.","rule":"Policy can change if the loan is sold.","say":"\"If you ever send less than a full payment, this tells you what the lender does with it. Always call the servicer first if you're having trouble.\"","check":""},{"id":"p4-security","p":4,"cat":"p4","b":[5.88,66.1,43.14,30.42],"t":"Security Interest","v":"456 Somewhere Ave.","what":"The property is collateral; the lender can foreclose if the loan isn't paid.","rule":"","say":"\"The home secures the loan, so it's important to keep payments, taxes and insurance current.\"","check":""},{"id":"p4-escrow","p":4,"cat":"p4","b":[50.98,11.03,43.14,13.09],"t":"Escrow Account","v":"Will have an escrow (impound) account","what":"Whether the servicer collects and pays taxes and insurance.","rule":"Required for higher-priced mortgages (first 5 years), FHA, VA, USDA; conventional ≥ 80% LTV often requires it; CA may allow waivers with a fee/price adjustment.","say":"\"You'll have an impound account. Each month part of your payment goes into it, and the servicer pays your taxes and insurance for you.\"","check":"Waiver requested? Shows the no-escrow box and any waiver fee."},{"id":"p4-esc1","p":4,"cat":"p4","b":[50.98,24.18,43.14,4.22],"t":"Escrowed Property Costs over Year 1","v":"$2,473.56","what":"Total escrowed costs for the first year (taxes + insurance).","rule":"= monthly escrow × 12 ($206.13 × 12).","say":"\"About $2,474 a year for taxes and insurance is collected through your payment.\"","check":""},{"id":"p4-esc2","p":4,"cat":"p4","b":[50.98,30.5,43.14,4.22],"t":"Non-Escrowed Property Costs over Year 1","v":"$1,800.00 (HOA dues)","what":"Costs the borrower pays directly.","rule":"","say":"\"You'll pay $1,800 a year in HOA dues directly to the association.\"","check":"Mello-Roos / HOA / supplemental tax — anything not in escrow."},{"id":"p4-esc3","p":4,"cat":"p4","b":[50.98,37.19,43.14,2.91],"t":"Initial Escrow Payment","v":"$412.25","what":"Cushion deposited at closing = page 2 Section G.","rule":"","say":"\"This is the escrow cushion you paid at closing.\"","check":"= Section G."},{"id":"p4-esc4","p":4,"cat":"p4","b":[50.98,41.73,43.14,2.91],"t":"Monthly Escrow Payment","v":"$206.13","what":"Escrow portion of each monthly payment = page 1.","rule":"","say":"\"$206.13 of each payment goes to escrow.\"","check":""},{"id":"p4-noesc","p":4,"cat":"p4","b":[50.98,53.12,43.14,8.24],"t":"No Escrow (and Escrow Waiver Fee)","v":"Not checked","what":"Used when there's no escrow account — the borrower pays taxes and insurance directly; any waiver fee shows here.","rule":"","say":"\"If you'd chosen no impound account, you'd pay taxes and insurance yourself, usually in big lump sums.\"","check":""},{"id":"p4-future","p":4,"cat":"p4","b":[50.98,61.43,43.14,35.08],"t":"In the Future","v":"Escrow can change; consequences of not paying","what":"Escrow payments change with taxes/insurance; if property costs go unpaid the lender can add them to the loan, add escrow, or force-place insurance.","rule":"","say":"\"Your escrow is reviewed every year. If taxes or insurance go up, your payment goes up. Never let insurance lapse — lender-placed insurance costs much more.\"","check":""},{"id":"p5-top","p":5,"cat":"p5","b":[5.88,7.52,43.14,4.41],"t":"Total of Payments","v":"$285,803.36","what":"Everything paid over the life of the loan if payments are made as scheduled: principal, interest, mortgage insurance and loan costs (Section D).","rule":"Considered accurate if it's not understated by more than $100 (or overstated). If inaccurate it may need a corrected CD.","say":"\"If you keep this loan all 30 years and pay as scheduled, you'll pay about $285,803 in total. Most people sell or refinance well before then.\"","check":""},{"id":"p5-fc","p":5,"cat":"p5","b":[5.88,13.17,43.14,3.1],"t":"Finance Charge","v":"$118,830.27","what":"The dollar cost of credit: interest + MI + prepaid finance charges (points, most lender fees, prepaid interest).","rule":"Tolerance: accurate if understated by no more than $100 (§1026.18(d)). Used to compute the APR.","say":"\"This is what the loan costs you over its life in dollars — mostly interest.\"","check":""},{"id":"p5-af","p":5,"cat":"p5","b":[5.88,17.56,43.14,3.1],"t":"Amount Financed","v":"$162,000.00","what":"Loan amount minus prepaid finance charges — the base for the APR.","rule":"","say":"\"This is the amount the APR is calculated on.\"","check":""},{"id":"p5-apr","p":5,"cat":"p5","b":[5.88,21.94,43.14,4.41],"t":"APR","v":"4.174%","what":"The yearly cost of the loan including fees — higher than the note rate because it includes points, fees and MI.","rule":"If the APR becomes inaccurate (increases more than 1/8% on a regular loan, 1/4% irregular) a NEW 3-business-day waiting period is required.","say":"\"Your interest rate is 3.875%. The APR of 4.174% adds in your fees and mortgage insurance so you can compare loans apples to apples.\"","check":"Compare to LE APR; jump > 0.125% → new 3-day wait."},{"id":"p5-tip","p":5,"cat":"p5","b":[5.88,27.59,43.14,4.41],"t":"Total Interest Percentage (TIP)","v":"69.46%","what":"Total interest over the life of the loan as a percentage of the loan amount.","rule":"","say":"\"Over 30 years you'd pay interest equal to about 69% of what you borrowed.\"","check":""},{"id":"p5-apprl","p":5,"cat":"p5","b":[50.98,7.57,43.14,7.89],"t":"Appraisal","v":"Copy required 3 days before closing","what":"Right to a free copy of the appraisal.","rule":"ECOA/Reg B §1002.14: copy promptly and at least 3 business days before consummation (waivable).","say":"\"You'll get a copy of the appraisal at no cost at least three days before closing.\"","check":"Delivery documented."},{"id":"p5-contract","p":5,"cat":"p5","b":[50.98,15.53,43.14,10.54],"t":"Contract Details","v":"See note and deed of trust","what":"Points the borrower to the note/security instrument for default, acceleration and prepayment terms.","rule":"","say":"\"The note and deed of trust you sign have the full legal details.\"","check":""},{"id":"p5-liab","p":5,"cat":"p5","b":[50.98,26.13,43.14,12.62],"t":"Liability after Foreclosure","v":"State law may protect you","what":"Whether the borrower can owe a deficiency after a foreclosure.","rule":"California anti-deficiency law (CCP §580b) generally protects purchase-money loans on owner-occupied 1–4 units; a refinance or additional debt can change that protection. Not legal advice.","say":"\"In California, a purchase loan on your own home generally can't come after you for a shortfall after foreclosure — but refinancing later can change that. For specifics, talk to an attorney.\"","check":"CA purchase: 'state law may protect you' box checked."},{"id":"p5-refi","p":5,"cat":"p5","b":[50.98,38.82,43.14,6.57],"t":"Refinance","v":"Not guaranteed","what":"No promise that a future refinance will be available.","rule":"Never promise a future refinance to sell a loan.","say":"\"You might be able to refinance later if rates drop, but that depends on your finances, the home's value and the market — it isn't guaranteed.\"","check":""},{"id":"p5-tax","p":5,"cat":"p5","b":[50.98,45.45,43.14,5.73],"t":"Tax Deductions","v":"","what":"Interest on debt above fair market value isn't deductible.","rule":"Refer tax questions to a tax advisor.","say":"\"For tax questions, check with your tax advisor.\"","check":""},{"id":"p5-q","p":5,"cat":"p5","b":[15.52,38.14,33.5,8.51],"t":"Questions?","v":"CFPB contact","what":"Where to get help or file a complaint.","rule":"","say":"\"If anything is unclear, call me first — and you can always contact the Consumer Financial Protection Bureau.\"","check":""},{"id":"p5-contact","p":5,"cat":"p5","b":[5.88,53.2,88.24,31.09],"t":"Contact Information","v":"Lender · Mortgage Broker · Agents · Settlement Agent","what":"Names, addresses, NMLS and state license IDs and the contact person for each party.","rule":"Mortgage broker and loan officer NMLS IDs are required. For our loans: Patriot Pacific Financial Corp NMLS 1921615 · Steven Shearrill NMLS 2449246 · CA DRE 01988316.","say":"\"Here's everyone involved and how to reach them. I'm listed as your loan officer with my NMLS and license numbers.\"","check":"Broker column filled in with our NMLS/DRE IDs."},{"id":"p5-sign","p":5,"cat":"p5","b":[5.88,84.36,88.24,8.51],"t":"Confirm Receipt","v":"Applicant signature","what":"Signature acknowledges RECEIPT only.","rule":"Signing does not mean the borrower accepts the loan or must close.","say":"\"Signing here only says you received this form — it doesn't commit you to the loan.\"","check":"Signed/e-signed receipt date ≥ 3 business days before closing."}]};
